"d:налево": "chapga",
"d:направо": "o‘ngga",
"d:назад": "orqaga",
"d:вперёд": "oldinga",
"Записываем числа в столбик: единицы под единицами, десятки под десятками. Начинаем с единиц.": "Sonlarni ustun qilib yozamiz: birliklar birliklar tagiga, o‘nliklar o‘nliklar tagiga. Birliklardan boshlaymiz.",
"У числа 100 нет ни десятков, ни единиц. Разменяем сотню: 100 = 9 десятков и 10 единиц.": "100 sonida o‘nlik ham, birlik ham yo‘q. Yuzlikni maydalaymiz: 100 = 9 o‘nlik va 10 birlik.",
"Это однозначное число: в нём только единицы.": "Bu bir xonali son: unda faqat birliklar bor.",
"100 — это 10 десятков. Перед ним 99. После него — 101.": "100 — bu 10 o‘nlik. Undan oldin 99 keladi. Undan keyin — 101.",
"Хорошо! Числа идут по порядку: каждое следующее на 1 больше.": "Yaxshi! Sonlar tartib bilan boradi: har bir keyingisi 1 ga ko‘p.",
"10 единиц — это 1 десяток! Собираем их в палочку.": "10 birlik — bu 1 o‘nlik! Ularni tayoqchaga yig‘amiz.",
"Десяток разменяли на 10 единиц и одну убрали.": "Bir o‘nlikni 10 birlikka almashtirdik va bittasini olib tashladik.",
"Все числа собраны! 🌟": "Barcha sonlar yig‘ildi! 🌟",
"Нажми «+ сотня»": "«+ yuzlik» tugmasini bos",
"10 сотен — это 1000, тысяча! Одна сотня — это 10 десятков, то есть 100.": "10 yuzlik — bu 1000, ming! Bir yuzlik — bu 10 o‘nlik, ya’ni 100.",
"Тысяча! Дальше считать сотнями не нужно.": "Ming! Endi yuzliklab sanash shart emas.",
"Выбери, как считать 👆": "Qanday sanashni tanla 👆",
"по 3": "3 tadan",
"по 4": "4 tadan",
"по 5": "5 tadan",
"Все три счёта посмотрели!": "Uchala sanashni ham ko‘rding!",
"Один кружок остался без пары.": "Bitta doira juftsiz qoldi.",
"Все кружки встали в пары, лишнего нет.": "Hamma doiralar juft-juft bo‘lib turdi, ortig‘i yo‘q.",
"Замечаешь? Чётные числа оканчиваются на 0, 2, 4, 6, 8. Нечётные — на 1, 3, 5, 7, 9.": "Payqadingmi? Juft sonlar 0, 2, 4, 6, 8 bilan tugaydi. Toq sonlar — 1, 3, 5, 7, 9 bilan.",
"Нужно посмотреть несколько чётных и несколько нечётных чисел.": "Bir nechta juft va bir nechta toq sonni ko‘rish kerak.",
"На сколько равных частей делим?": "Nechta teng qismga bo‘lamiz?",
"Хорошо! Равные части — это когда в каждой одинаково.": "Yaxshi! Teng qismlar — bu har birida bir xil bo‘lishi.",
"Попробуй ещё несколько делений.": "Yana bir nechta bo‘lishni sinab ko‘r.",
"Алгоритм понятен! Теперь потренируемся сами.": "Algoritm tushunarli! Endi o‘zimiz mashq qilamiz.",
"Следующий шаг →": "Keyingi qadam →",
"групп": "guruh",
"в каждой по": "har guruhda",
"Это умножение:": "Bu ko‘paytirish:",
"Видишь? Умножение — это сложение одинаковых слагаемых.": "Ko‘rdingmi? Ko‘paytirish — bu bir xil qo‘shiluvchilarni qo‘shish.",
"Это прямой угол": "Bu to‘g‘ri burchak",
"Это острый угол": "Bu o‘tkir burchak",
"Это тупой угол": "Bu o‘tmas burchak",
"Прямой угол — как угол листа бумаги, угольника или квадрата.": "To‘g‘ri burchak — qog‘oz varag‘ining, chizma uchburchagining yoki kvadratning burchagiga o‘xshaydi.",
"Острый угол меньше прямого. Он острый, как кончик карандаша.": "O‘tkir burchak to‘g‘ri burchakdan kichik. U qalam uchidek o‘tkir.",
"Тупой угол больше прямого. Стороны «раскрылись» шире.": "O‘tmas burchak to‘g‘ri burchakdan katta. Tomonlari kengroq «ochilgan».",
"Все три вида углов найдены!": "Burchakning uchala turi ham topildi!",
"Начать заново": "Qaytadan boshlash",
"Все чертежи готовы! 🌟": "Barcha chizmalar tayyor! 🌟",
"Не та точка. Пройди путь по шагам от красной точки, считая клетки.": "Bu nuqta emas. Qizil nuqtadan boshlab yo‘lni qadamma-qadam bos, kataklarni sanab.",
"Это не прямой угол. Стороны должны идти по клеточным линиям: одна вдоль, другая поперёк.": "Bu to‘g‘ri burchak emas. Tomonlar katak chiziqlari bo‘ylab bo‘lishi kerak: biri bo‘ylama, ikkinchisi ko‘ndalang.",
"длина": "uzunlik",
"ширина": "kenglik",
"клеток": "katak",
"Все фигуры построены! 🌟": "Barcha shakllar yasaldi! 🌟",
"У квадрата длина и ширина одинаковые.": "Kvadratning uzunligi va kengligi bir xil.",
"↻ четверть по часовой": "↻ soat mili bo‘ylab chorak",
"↺ четверть против часовой": "↺ soat miliga qarshi chorak",
"½ поворота": "½ burilish",
"Ты попробовал все повороты!": "Sen barcha burilishlarni sinab ko‘rding!",
"Раздели прямоугольник на два квадрата (нажми на линию разреза)": "To‘g‘ri to‘rtburchakni ikkita kvadratga bo‘l (kesish chizig‘ini bos)",
"Раздели прямоугольник на два одинаковых прямоугольника (нажми на линию разреза)": "To‘g‘ri to‘rtburchakni ikkita bir xil to‘g‘ri to‘rtburchakka bo‘l (kesish chizig‘ini bos)",
"Раздели прямоугольник на квадрат и прямоугольник (нажми на линию разреза)": "To‘g‘ri to‘rtburchakni kvadrat va to‘g‘ri to‘rtburchakka bo‘l (kesish chizig‘ini bos)",
"Не то, что нужно. Попробуй другую линию.": "Bu kerakli emas. Boshqa chiziqni sinab ko‘r.",
"Все фигуры разрезаны! 🌟": "Barcha shakllar kesildi! 🌟",
"− час": "− soat",
