"Все часы поставлены! 🌟": "Barcha soatlar qo‘yildi! 🌟",
"Такой комплект уже есть. Ищи новый.": "Bunday to‘plam allaqachon bor. Yangisini izla.",
"Есть!": "Topildi!",
"Все комбинации найдены! 🌟": "Barcha kombinatsiyalar topildi! 🌟",
"Опрос закончен! Вот таблица и диаграмма.": "So‘rovnoma tugadi! Mana jadval va diagramma.",
"Теперь можно тренироваться в тренажёрах «Математики 2 класса»: задания каждый раз новые.": "Endi «2-sinf matematikasi» trenajyorlarida mashq qilishing mumkin: topshiriqlar har safar yangi.",
"Тренажёры 2 класса →": "2-sinf trenajyorlari →",
